SITES.ajpw = {"base": "https://shovan123-lang.github.io/AJPW/HTML/", "arch": [["Summer Action Series 1991", [["Night 1 · Tokyo, Korakuen Hall · 7.1", "SUMMER_A"], ["Night 2 · Chiba Port Arena · 7.3", "CHIBA__C"], ["Night 3 · Sendai City Gym · 7.5", "SENDI__S"], ["Night 4 · Niigata City Gym · 7.7", "NIGATA__"], ["Night 5 · Kanazawa, Ishikawa Gym · 7.9", "KANAZAWA"], ["Night 6 · Nagoya, Aichi Gym · 7.11", "NAGOYA__"], ["Night 7 · Hiroshima, Sun Plaza · 7.13", "HIROSHIM"], ["Night 8 · Okayama Budokan · 7.15", "OKAYAMA_"], ["Night 9 · Kumamoto Prefectural Gym · 7.17", "KUMAMOTO"], ["Night 10 · Fukuoka Sports Center · 7.19", "FUKUOKA_"], ["Night 11 · Sapporo, Nakajima Sports Center · 7.21", "SAPPORO_"]]]], "label": "Summer Action Series show pages"};
Object.assign(ARTICLES, {"ajpw-misawa-pins-hansen-0721": {"p": "ajpw", "kicker": "Summer Action Series Report · Sapporo, July 21", "title": "Misawa Puts Hansen Down, Then Calls Out the Champions", "dek": "Misawa pins Stan Hansen with the Tiger Driver and challenges MVC for Yokohama. Rude comes back to Japan a champion, and Jumbo walks away without a word.", "by": "All Japan Pro Wrestling", "date": "1991-07-21", "factTitle": "The Card", "facts": [["Main", "Misawa & Jumbo d. Hansen & Gordy"], ["Best match", "Rude d. Furnas, ****"], ["Next", "MVC vs. Misawa & Kobashi, Yokohama 7/23"], ["Crowd", "4,000"]], "body": [["p", "All Japan's northern swing opened in Sapporo with Mitsuharu Misawa and Jumbo Tsuruta on the same side of the ring, and they left together as winners. After 18 hard minutes with Stan Hansen and Terry Gordy, Misawa survived a Hansen bearhug, broke free and dropped him with the Tiger Driver for the pin at 18:38. Pinning Hansen is something very few men in this company can say they've done."], ["p", "Then Misawa took the microphone and called Kenta Kobashi to the ring. On Tuesday in Yokohama, Super Generation challenges the Miracle Violence Connection for the World Tag Team titles. Steve Williams answered from the ramp with both belts over his head and a warning for Jumbo: Budokan is six days away. Jumbo stood between Misawa and the ramp and said nothing. When Williams and Gordy were gone, he left the ring without a word to his partner."], ["h", "Rude Is Back, and He's a Champion"], ["p", "Two nights after winning the WCW United States title in Charleston, West Virginia, Rick Rude came back to Japan with the belt and the best match of the night. Doug Furnas pushed him for twelve minutes, with Dan Kroffat urging him on from the corner, but Rude caught him with the Rude Awakening for the pin at 12:31. After a hard tour, Rude finally looks like the star he came here as. Johnny Ace is next, at Budokan."], ["h", "Funk Taps Fuchi"], ["p", "Dory Funk Jr. stood beside Steve Williams again, and again it worked. Funk tied up Masanobu Fuchi in the spinning toe hold and Fuchi had to give up at 16:25. Williams and Funk beat Fuchi and Akira Taue, and Williams still hasn't been pinned on this tour."], ["h", "Ace Sharpens up for Rude"], ["p", "Johnny Ace opened the night with a strong win over Tsuyoshi Kikuchi, pinning him with the Implant DDT at 10:24."], ["h", "The Fantastics Get One Back"], ["p", "Tommy Rogers rolled up Davey Boy Smith at 13:08 to give the Fantastics a win over the British Bulldogs. The Fantastics get their All Asia Tag title shot at Budokan."], ["h", "The Malenkos' Revenge"], ["p", "Two nights after Yoshinari Ogawa pinned Dean Malenko, Joe Malenko evened the score. With Dean in his corner, Joe locked Ogawa in the Final Lesson and wouldn't let go. Ogawa passed out, and the referee stopped it at 14:38."], ["h", "Around the Ring"], ["p", "Kenta Kobashi had an easy night before Yokohama. He and Masao Inoue beat Too Cold Scorpio and Billy Joe Travis when Kobashi flattened Travis with the running lariat at 10:29. Abdullah the Butcher and Giant Kimala II were thrown out at 7:09 against Rusher Kimura and Haruka Eigen. Jumbo Tsuruta, who has his own score to settle with Abdullah over Giant Baba, came to ringside, and in the confusion Eigen went down over Jumbo's foot. The referee had seen enough of Abdullah and Kimala II and disqualified them."], ["p", "Next for All Japan: Yokohama on Tuesday, July 23. The Miracle Violence Connection defend the World Tag Team titles against Misawa and Kobashi."], ["p", "Card rating: ***1/4 Match of the night: Rick Rude vs. Doug Furnas ****"]]}, "ajpw-observer-sapporo-0721": {"p": "ajpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-21", "region": "Japan Report", "kicker": "AJPW · Summer Action Series, Night 11 · Sapporo, July 21", "title": "Sapporo: Misawa Gets the Fall That Matters", "dek": "Misawa pins Hansen clean, Jumbo can't get out of the ring fast enough, Rude has his best match of the tour, and the tour gate closes in on a million.", "factTitle": "Match observations", "facts": [["City", "Sapporo"], ["Attendance", "4,000"], ["Gate", "$120,000"], ["Merchandise", "$8,000 ($2 per fan)"], ["Card", "***1/4"], ["Match of the show", "Rude vs. Furnas, ****"]], "body": [["p", "All Japan opened its northern swing on Sunday with 4,000 at the Nakajima Sports Center at a $30 average for $120,000, plus $8,000 in merchandise at $2 a head. That's a little under the $128,250 they did in Fukuoka on Friday, and it leaves the Summer Action Series just short of a million dollars in gates through eleven nights, at $993,507. The tour goes over the million in Yokohama on Tuesday no matter what it draws. The card came in at ***1/4, and nobody was hurt."], ["p", "The main event was Mitsuharu Misawa and Jumbo Tsuruta over Stan Hansen and Terry Gordy in 18:38, ***3/4, and the finish was the story. Misawa pinned Hansen clean with the Tiger Driver. Hansen does not get pinned in this company very often, and giving the fall to Misawa, with Jumbo standing on the apron, tells you exactly who the office sees as the next man. Hansen gets Jumbo one on one in Osaka on Thursday, so he loses nothing he needs."], ["p", "What happened after the bell was better than the match. Misawa called Kenta Kobashi to the ring and challenged the Miracle Violence Connection for the World Tag Team titles in Yokohama on Tuesday. Steve Williams answered from the ramp with both belts over his head and a warning for Jumbo: Budokan is six days away. Jumbo stood between Misawa and the ramp, said nothing, and left the ring without a word to the man he had just teamed with. Three weeks ago at Korakuen Hall, Super Generation and Jumbo's side went to a twenty-minute draw on opening night. Nobody has explained what Jumbo was doing in Misawa's corner tonight, or why he couldn't get out of it fast enough."], ["p", "Jumbo also turned up at ringside earlier in the night. Abdullah the Butcher and Giant Kimala II were disqualified at 7:09 against Rusher Kimura and Haruka Eigen, DUD. Jumbo came out, apparently to get at Abdullah over what happened to Giant Baba in Chiba, and in the confusion Eigen went down over Jumbo's foot. The office is calling it an accident. Not everybody in the building saw it that way. Baba is still out with the neck and isn't expected back before the tour ends."], ["p", "The match of the night was Rick Rude over Doug Furnas in 12:31 with the Rude Awakening, ****. Two nights earlier Rude beat Sting for the WCW U.S. title in Charleston, WV. He got on a plane, crossed the Pacific, and had his best match of the tour. It's been a rough tour for him: upset by Bobby Fulton in Sendai, pinned by Misawa in Nagoya, beaten by Kobashi in Kumamoto. He came back with a belt and a different attitude, and the crowd treated him like a star for the first time. Furnas, with Dan Kroffat in his corner, gave him plenty and lost nothing. Rude gets Johnny Ace at Budokan, and Can-Am defend the All Asia titles there against the Fantastics."], ["p", "Williams and Dory Funk Jr. beat Akira Taue and Masanobu Fuchi in 16:25 when Funk made Fuchi submit to the spinning toe hold, ***1/2. Funk has been on MVC's side since Kumamoto and lost a Triple Crown match to Jumbo in Fukuoka two nights ago. Williams still hasn't been pinned on this tour, and that is the entire build for Budokan. Taue keeps working hard on Jumbo's side and keeps not getting credit for it."], ["p", "The Fantastics beat the British Bulldogs in 13:08, ***1/4, when Tommy Rogers rolled up Davey Boy Smith. The Fantastics beat Can-Am non-title in Okayama to earn the Budokan shot, and this keeps them moving."], ["p", "Johnny Ace opened with a win over Tsuyoshi Kikuchi in 10:24, ***1/4, with the Implant DDT. Ace has been one of the improved foreigners on the tour, and he goes into Budokan off a win over Too Cold Scorpio in Kumamoto and this one."], ["p", "Joe Malenko choked out Yoshinari Ogawa with the Final Lesson in 14:38, **1/2, with Dean in his corner. It got back the clean loss Dean took to Ogawa in Fukuoka, which was ****1/4. This was the weakest match the Malenkos and Ogawa have had, but it keeps the best undercard feud on the tour alive."], ["p", "Kobashi and Masao Inoue beat Scorpio and Billy Joe Travis in 10:29 when Kobashi hit Travis with the running lariat, ***. Kobashi was kept light before Yokohama, which is the right call."], ["h", "Results"], ["p", "1. Johnny Ace pinned Tsuyoshi Kikuchi with the Implant DDT in 10:24. ***1/4"], ["p", "2. Kenta Kobashi & Masao Inoue beat Too Cold Scorpio & Billy Joe Travis in 10:29 when Kobashi pinned Travis with a running lariat. ***"], ["p", "3. Rusher Kimura & Haruka Eigen beat Abdullah the Butcher & Giant Kimala II by DQ in 7:09. Jumbo Tsuruta came to ringside. DUD"], ["p", "4. Joe Malenko beat Yoshinari Ogawa in 14:38 when Ogawa passed out in the Final Lesson. **1/2"], ["p", "5. The Fantastics beat the British Bulldogs in 13:08 when Tommy Rogers rolled up Davey Boy Smith. ***1/4"], ["p", "6. Rick Rude pinned Doug Furnas with the Rude Awakening in 12:31. ****"], ["p", "7. Steve Williams & Dory Funk Jr. beat Akira Taue & Masanobu Fuchi in 16:25 when Funk made Fuchi submit to the spinning toe hold. ***1/2"], ["p", "8. Mitsuharu Misawa & Jumbo Tsuruta beat Stan Hansen & Terry Gordy in 18:38 when Misawa pinned Hansen with the Tiger Driver. ***3/4"], ["p", "9. Interview: Misawa calls out the Miracle Violence Connection."], ["p", "Overall card: ***1/4"], ["p", "Next is Yokohama on Tuesday: MVC defend the World Tag titles against Misawa and Kobashi. Then Osaka on Thursday, Jumbo vs. Hansen, and the tour ends at Budokan on Saturday."]]}, "ajpw-diary-ace-0721": {"p": "ajpw", "series": "diary", "by": "Johnny Ace", "date": "1991-07-21", "place": "Team hotel, Sapporo", "kicker": "From the Road · Sapporo, July 21", "title": "Nobody Ever Knows", "dek": "Johnny Ace on opening the show, a U.S. title belt on a dressing-room bench, and the man he gets at Budokan.", "factTitle": "The Night", "facts": [["Show", "Sapporo, Summer Action Series Night 11"], ["Match", "vs. Tsuyoshi Kikuchi"], ["Finish", "Implant DDT, 10:24"], ["Rating", "***1/4"], ["Next", "Rick Rude at Budokan, 7/27"]], "body": [["p", "It's cooler up here. That's the first thing everybody said getting off the bus. Three weeks of Japan in July and you forget what it feels like to walk outside without sweating through your shirt."], ["p", "They had me opening the show against Kikuchi. Some guys would take that as an insult. I don't. In this company the opener is where they find out whether you can go, and Kikuchi can go. He's small and he's tough and he doesn't stop coming. I hit him with everything I had for ten minutes and he kept getting up. When I finally got him in the Implant DDT, I knew that was it. The crowd gave us a nice hand. Up here they clap politely, and then once in a while they don't, and you know you've done something."], ["p", "Rude came in this morning. He flew straight from America, from some town in West Virginia, and he had the United States belt in his bag. He took it out in the dressing room and set it on the bench like it was nothing. Nobody said anything about it. Everybody looked at it."], ["p", "Then he went out and had the best match of the night with Doug Furnas. I watched the whole thing from the curtain. I've been watching him for three weeks, and this was a different guy. He used to come back through the curtain mad. Tonight he came back through, sat down, and asked for a towel. That's the man I get at Budokan on Saturday. Great."], ["p", "The main was something else. Misawa pinned Hansen. I didn't know that was allowed. Hansen came back holding his neck, sat in the corner, and didn't say a word to anybody. Gordy got him a water."], ["p", "After that, Misawa called out Kobashi, and Doc came down the ramp with the belts. Jumbo stood there. I was standing next to Dan Kroffat behind the curtain and he said, \"Jumbo's thinking about something.\" I asked what. He said, \"Nobody ever knows.\""], ["p", "Yokohama on Tuesday. I don't know yet what they've got me doing there. I've got four days to figure out how to beat Rick Rude, and I'll need every one of them."]]}});

