Object.assign(ARTICLES, {"ajpw-jumbo-answers-funk-0719": {"p": "ajpw", "news": 1, "by": "Newsletter staff", "date": "1991-07-19", "region": "Japan Report", "kicker": "All Japan · Fukuoka Sports Center, July 19", "title": "Jumbo Answers Funk", "dek": "Dory Funk Jr. lined up with the Miracle Violence Connection. Two nights later Jumbo beat him for the Triple Crown.", "body": [["p", "Dory Funk Jr. teamed with Steve Williams and Terry Gordy against Jumbo Tsuruta's team in Kumamoto on July 17, and Williams pinned Masanobu Fuchi with the Doctor Bomb (****). Two nights later in Fukuoka, Jumbo answered: he beat Funk with the backdrop driver in 16:40 to keep the Triple Crown (***3/4)."], ["p", "It was Jumbo's second successful defense in four nights, after Kenta Kobashi took him to 18:55 in Okayama. Williams is next, at Budokan."]], "facts": [["Match", "Jumbo Tsuruta (c) d. Dory Funk Jr."], ["Finish", "backdrop driver, 16:40"], ["Rating", "***3/4"], ["Title", "Triple Crown retained"], ["Next", "Steve Williams, Budokan"]], "factTitle": "The Title Match"}, "ajpw-jumbo-at-ringside-0721": {"p": "ajpw", "news": 1, "by": "Newsletter staff", "date": "1991-07-21", "region": "Japan Report", "kicker": "All Japan · Nakajima Sports Center, Sapporo, July 21", "title": "Jumbo at Ringside", "dek": "Jumbo came out during an Abdullah match in Sapporo, and Haruka Eigen went down over his foot.", "body": [["p", "Abdullah the Butcher and Giant Kimala II were disqualified against Rusher Kimura and Haruka Eigen at 7:09 in Sapporo, and the finish wasn't the story. Jumbo Tsuruta came to ringside during the match, apparently to get at Abdullah over Giant Baba, and Eigen went down over his foot."], ["p", "The office calls it an accident. Jumbo left the building at the end of the night without a word to Mitsuharu Misawa, after Misawa called out the Miracle Violence Connection. What Jumbo was doing out there is To establish."]], "facts": [["Match", "Kimura & Eigen d. Abdullah & Kimala II"], ["Result", "DQ, 7:09"], ["Jumbo", "came to ringside"], ["Eigen", "went down over his foot"], ["Office", "calls it an accident"]], "factTitle": "The Moment"}, "ajpw-ogawa-gets-even-0719": {"p": "ajpw", "news": 1, "by": "Newsletter staff", "date": "1991-07-19", "region": "Japan Report", "kicker": "All Japan · Kumamoto, Fukuoka and Sapporo, July 17–21", "title": "Ogawa Gets Even", "dek": "The Malenkos cheated Ogawa in Kumamoto. He pinned Dean clean in Fukuoka, and Joe got it back in Sapporo.", "body": [["p", "In Kumamoto on July 17, Dean Malenko pinned Tsuyoshi Kikuchi with his feet on the ropes to beat Yoshinari Ogawa and Kikuchi (***1/4). Two nights later in Fukuoka, Ogawa pinned Dean clean with a small package in 14:08. It went ****1/4."], ["p", "Joe Malenko evened it in Sapporo on July 21, choking Ogawa out with the Final Lesson in 14:38. Ogawa has beaten both Malenkos one-on-one this month, and they keep finding a way back."]], "facts": [["July 17", "Malenkos d. Ogawa & Kikuchi (feet on the ropes)"], ["July 19", "Ogawa d. Dean Malenko, small package, ****1/4"], ["July 21", "Joe Malenko d. Ogawa, Final Lesson, 14:38"], ["Earlier", "Ogawa d. Joe Malenko, Okayama 7/15"], ["Next", "To establish"]], "factTitle": "The Series"}, "ajpw-rude-returns-champion-0721": {"p": "ajpw", "news": 1, "by": "Newsletter staff", "date": "1991-07-21", "region": "Japan Report", "kicker": "All Japan · Nakajima Sports Center, Sapporo, July 21", "title": "Rude Returns a Champion", "dek": "Rick Rude spent three weeks losing in All Japan. He came back to Sapporo as WCW U.S. Champion and won.", "body": [["p", "Rick Rude came to All Japan as a star and lost more than he won: Bobby Fulton upset him in Sendai, Misawa pinned him in Nagoya, and Kenta Kobashi beat him with the moonsault in Kumamoto. Then he flew home, beat Sting for the WCW U.S. Title in Charleston, WV on July 19, and came back to Sapporo two nights later with the belt."], ["p", "He beat Doug Furnas with the Rude Awakening in 12:31, and it was the match of the night (****). Johnny Ace is next, at Budokan."]], "facts": [["Match", "Rick Rude d. Doug Furnas"], ["Finish", "Rude Awakening, 12:31"], ["Rating", "****, match of the night"], ["Belt", "WCW U.S. Champion since 7/19"], ["Next", "Johnny Ace, Budokan"]], "factTitle": "The Return"}});
